/**
 * Mock backend for `?mock=1`. Serves the documented "Completed Task Response" example of each
 * endpoint (src/data/fixtures.json, generated by scripts/build-fixtures.mjs from the SocQ docs),
 * after a short simulated queue. It makes no network requests and never needs a key.
 *
 * Tip: any input value containing the word "fail" produces a failed task.
 */
import fixtures from '../data/fixtures.json';
import type { Account, ApiClient, TaskFile, TaskPage } from './api';
import { ApiError, parseTask } from './api';
import { findEndpoint } from '../data/catalog';

interface MockTask {
  endpointId: string;
  createdAt: number;
  fail: boolean;
}

const KEY = 'osms.mock.tasks';
const responses = (fixtures as unknown as { responses: Record<string, Parameters<typeof parseTask>[0]> }).responses;

function load(): Record<string, MockTask> {
  try {
    return JSON.parse(sessionStorage.getItem(KEY) ?? '{}') as Record<string, MockTask>;
  } catch {
    return {};
  }
}

function save(tasks: Record<string, MockTask>) {
  try {
    sessionStorage.setItem(KEY, JSON.stringify(tasks));
  } catch {
    /* ignore */
  }
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
const QUEUED_MS = 700;
const DONE_MS = 2400;

export const mockClient: ApiClient = {
  async submit(endpointId, body) {
    await delay(350);
    if (!findEndpoint(endpointId) || !responses[endpointId]) throw new ApiError(`Unknown endpoint ${endpointId}`, 404);
    const taskId = `MOCK${Date.now().toString(36).toUpperCase()}${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
    const tasks = load();
    tasks[taskId] = { endpointId, createdAt: Date.now(), fail: /\bfail/i.test(JSON.stringify(body)) };
    save(tasks);
    return { taskId, status: 'queued' };
  },

  async task(taskId, opts = {}): Promise<TaskPage> {
    await delay(120);
    const t = load()[taskId];
    if (!t) throw new ApiError('Task not found', 404);
    const elapsed = Date.now() - t.createdAt;
    const meta = { taskId, resultCount: null, credits: null, error: null };
    if (elapsed < QUEUED_MS) return { ...meta, status: 'queued' };
    if (elapsed < DONE_MS) return { ...meta, status: 'running' };
    if (t.fail) return { ...meta, status: 'failed', credits: 0, error: 'Mock failure: an input value contained "fail".' };
    const page = parseTask({ ...responses[t.endpointId], task_id: taskId });
    // The documented example is a single page; later cursors return nothing.
    const items = opts.cursor ? [] : page.results?.items ?? [];
    return {
      ...page,
      results: { items, nextCursor: null, hasMore: false, schemaId: page.results?.schemaId },
    };
  },

  async files(): Promise<TaskFile[]> {
    await delay(150);
    return [];
  },

  async account(): Promise<Account> {
    await delay(100);
    return { email: null, credits: null, plan: null, demo: true };
  },
};
